window.BOOK={"key":"antara","app":"mutoon-antara","lsk":"mutoon_antara_v1","prefix":"an_","title":"معلقة عنترة بن شداد","sub":"معلقة · عنترة بن شداد (ت نحو ٦٠٨م) · ٧٥ بيتًا","poems":[{"id":"antara","title":"معلقة عنترة بن شداد","nazim":"عنترة بن شداد العبسي","death":"ت نحو ٦٠٨م","meter":"الكامل","source":"المكتبة الشاملة: شرح المعلقات السبع للزوزني (دار إحياء التراث العربي، ط١ ١٤٢٣هـ)","srcUrl":"https://shamela.ws/book/11253/268","note":"نص المعلقة برواية الزوزني وعدّه وترتيبه (٧٥ بيتًا)، قوبل كلمةً كلمةً بسكربت بشرح القصائد العشر للتبريزي وشرح القصائد السبع لابن الأنباري. أُكمل الشكل من الشرحين حيث اتفقت الكلمة، وصُحّحت أخطاء الطبع والوزن، وكل ذلك في تقرير المصادر.","verses":[["هَلْ غَادَرَ الشُّعَرَاءُ مِنْ مُتَرَدَّمِ","أَمْ هَلْ عَرَفْتَ الدَّارَ بَعْدَ تَوَهُّمِ"],["يَا دَارَ عَبْلَةَ بِالْجِوَاءِ تَكَلَّمِي","وَعِمِي صَبَاحًا دَارَ عَبْلَةَ وَاسْلَمِي"],["فَوَقَفْتُ فِيهَا نَاقَتِي وَكَأَنَّهَا","فَدَنٌ لأَقْضِيَ حَاجَةَ الْمُتَلَوِّمِ"],["وَتَحُلُّ عَبْلَةُ بِالْجِوَاءِ وَأَهْلُنَا","بِالْحَزْنِ فَالصَّمَّانِ فَالْمُتَثَلَّمِ"],["حُيِّيتَ مِنْ طَلَلٍ تَقَادَمَ عَهْدُهُ","أَقْوَى وَأَقْفَرَ بَعْدَ أُمِّ الْهَيْثَمِ"],["حَلَّتْ بِأَرْضِ الزَّائِرِينَ فَأَصْبَحَتْ","عَسِرًا عَلَيَّ طِلَابُكِ ابْنَةَ مَخْرَمِ"],["عُلِّقْتُهَا عَرَضًا وَأَقْتُلُ قَوْمَهَا","زَعْمًا لَعَمْرُ أَبِيكَ لَيْسَ بِمَزْعَمِ"],["وَلَقَدْ نَزَلْتِ فَلَا تَظُنِّي غَيْرَهُ","مِنِّي بِمَنْزِلَةِ الْمُحَبِّ الْمُكْرَمِ"],["كَيْفَ الْمَزَارُ وَقَدْ تَرَبَّعَ أَهْلُهَا","بِعُنَيْزَتَيْنِ وَأَهْلُنَا بِالْغَيْلَمِ"],["إِنْ كُنْتِ أَزْمَعْتِ الْفِرَاقَ فَإِنَّمَا","زُمَّتْ رِكَابُكُمُ بِلَيْلٍ مُظْلِمِ"],["مَا رَاعَنِي إِلَّا حَمُولَةُ أَهْلِهَا","وَسْطَ الدِّيَارِ تَسَفُّ حَبَّ الْخِمْخِمِ"],["فِيهَا اثْنَتَانِ وَأَرْبَعُونَ حَلُوبَةً","سُودًا كَخَافِيَةِ الْغُرَابِ الْأَسْحَمِ"],["إِذْ تَسْتَبِيكَ بِذِي غُرُوبٍ وَاضِحٍ","عَذْبٍ مُقَبَّلُهُ لَذِيذِ الْمَطْعَمِ"],["وَكَأَنَّ فَارَةَ تَاجِرٍ بِقَسِيمَةٍ","سَبَقَتْ عَوَارِضَهَا إِلَيْكَ مِنَ الْفَمِ"],["أَوْ رَوْضَةً أُنُفًا تَضَمَّنَ نَبْتَهَا","غَيْثٌ قَلِيلُ الدِّمْنِ لَيْسَ بِمَعْلَمِ"],["جَادَتْ عَلَيْهِ كُلُّ بِكْرٍ حُرَّةٍ","فَتَرَكْنَ كُلَّ قَرَارَةٍ كَالدِّرْهَمِ"],["سَحًّا وَتَسْكَابًا فَكُلَّ عَشِيَّةٍ","يَجْرِي عَلَيْهَا الْمَاءُ لَمْ يَتَصَرَّمِ"],["وَخَلَا الذُّبَابُ بِهَا فَلَيْسَ بِبَارِحٍ","غَرِدًا كَفِعْلِ الشَّارِبِ الْمُتَرَنِّمِ"],["هَزِجًا يَحُكُّ ذِرَاعَهُ بِذِرَاعِهِ","قَدْحَ الْمُكِبِّ عَلَى الزِّنَادِ الْأَجْذَمِ"],["تُمْسِي وَتُصْبِحُ فَوْقَ ظَهْرِ حَشِيَّةٍ","وَأَبِيتُ فَوْقَ سَرَاةِ أَدْهَمَ مُلْجَمِ"],["وَحَشِيَّتِي سَرْجٌ عَلَى عَبْلِ الشَّوَى","نَهْدٍ مَرَاكِلُهُ نَبِيلِ الْمَحْزِمِ"],["هَلْ تُبْلِغَنِّي دَارَهَا شَدَنِيَّةٌ","لُعِنَتْ بِمَحْرُومِ الشَّرَابِ مُصَرَّمِ"],["خَطَّارَةٌ غِبَّ السُّرَى زَيَّافَةٌ","تَطِسُ الْإِكَامَ بِوَخْذِ خُفٍّ مِيثَمِ"],["وَكَأَنَّمَا تَطِسُ الْإِكَامَ عَشِيَّةً","بِقَرِيبِ بَيْنَ الْمَنْسِمَيْنِ مُصَلَّمِ"],["تَأْوِي لَهُ قُلُصُ النَّعَامِ كَمَا أَوَتْ","حِزَقٌ يَمَانِيَةٌ لأَعْجَمَ طِمْطِمِ"],["يَتْبَعْنَ قُلَّةَ رَأْسِهِ وَكَأَنَّهُ","حِدْجٌ عَلَى نَعْشٍ لَهُنَّ مُخَيَّمِ"],["صَعْلٍ يَعُودُ بِذِي الْعُشَيْرَةِ بَيْضَهُ","كَالْعَبْدِ ذِي الْفَرْوِ الطَّوِيلِ الْأَصْلَمِ"],["شَرِبتْ بِمَاءِ الدُّحْرُضَيْنِ فأَصْبَحَتْ","زَوْرَاءَ تَنْفِرُ عَنْ حِيَاضِ الدَّيلَمِ"],["وَكَأَنَّمَا تَنْأَى بِجَانِبِ دَفِّهَا الْ","وَحْشِيِّ مِنْ هَزِجِ العشِيِّ مُؤَوَّمِ"],["هِرّ جَنِيب كُلَّمَا عَطَفَتْ لَهُ","غَضْبَى اتَّقَاهَا بِالْيَدَيْنِ وَبِالْفَمِ"],["بَرَكَتْ عَلَى جَنْبِ الرِّدَاعِ كَأَنَّمَا","بَرَكَتْ عَلَى قَصَبٍ أَجَشَّ مُهَضَّمِ"],["وَكَأَنَّ رُبًّا أَوْ كُحَيْلًا مُعْقَدًا","حَشَّ الْوَقُودُ بِهِ جَوَانِبَ قُمْقُمِ"],["يَنْبَاعُ مِنْ ذِفْرَى غَضُوبٍ جَسْرَةٍ","زَيّافَةٍ مِثْلِ الْفَنيقِ الْمُكْدَمِ"],["إِنْ تُغْدِفِي دُونِي الْقِنَاعَ فَإِنَّنِي","طَبٌّ بأَخْذِ الْفَارِسِ الْمُسْتَلْئِمِ"],["أَثْنِي عَلَيَّ بِمَا عَلِمْتِ فَإِنَّنِي","سَمْحٌ مُخَالَقَتِي إِذَا لَمْ أُظْلَمِ"],["وَإِذَا ظُلِمْتُ فَإِنَّ ظُلْمِي بَاسِلٌ","مُرٌّ مَذَاقَتُهُ كَطَعْمِ الْعَلْقَمِ"],["وَلَقَدْ شَرِبْتُ مِنَ الْمُدَامَةِ بَعْدَمَا","رَكَدَ الْهَوَاجِرُ بِالْمَشُوفِ الْمُعْلَمِ"],["بِزُجَاجَةٍ صَفْرَاءَ ذَاتِ أَسِرَّةٍ","قُرِنَتْ بِأَزْهَرَ فِي الشِّمَالِ مُفَدَّمِ"],["فَإِذَا شَرِبْتُ فَإِنَّنِي مُسْتَهْلِكٌ","مَالِي وَعِرْضِي وَافِرٌ لَمْ يُكْلَمِ"],["وَإِذَا صَحَوْتُ فَمَا أُقَصِّرُ عَنْ نَدًى","وَكَمَا عَلِمْتِ شَمَائِلِي وَتَكَرُّمِي"],["وَحَلِيلِ غَانِيَةٍ تَرَكْتُ مُجَدَّلًا","تَمْكُو فَرِيصَتُهُ كَشِدْقِ الْأَعْلَمِ"],["سَبَقَتْ يَدَايَ لَهُ بِعَاجِلِ طَعْنَةٍ","وَرَشَاشِ نَافِذَةٍ كَلَوْنِ الْعَنْدَمِ"],["هَلّا سَأَلْتِ الْخَيْلَ يَابْنَةَ مَالِكٍ","إِنْ كُنْتِ جَاهِلَةً بِمَا لَمْ تَعْلَمِي"],["إِذْ لَا أَزَالُ عَلَى رِحَالَةِ سَابِحٍ","نَهْدٍ تَعَاوَرُهُ الْكُمَاةُ مُكَلَّمِ"],["طَوْرًا يُجَرَّدُ لِلطِّعَانِ وَتَارَةً","يَأْوِي إِلَى حَصِدِ الْقِسِيِّ عَرَمْرَمِ"],["يُخْبِرْكِ مَنْ شَهِدَ الْوَقِيعَةَ أَنَّنِي","أَغْشَى الْوَغَى وَأَعِفُّ عِنْدَ الْمَغْنَمِ"],["وَمُدَجَّجٍ كَرِهَ الْكُمَاةُ نِزَالَهُ","لَا مُمْعِنٍ هَرَبًا وَلَا مُسْتَسْلِمِ"],["جَادَتْ لَهُ كَفِّي بِعَاجِلِ طَعْنَةٍ","بِمُثَقَّفٍ صَدْقِ الْكُعُوبِ مُقَوَّمِ"],["فَشَكَكْتُ بِالرُّمْحِ الْأَصَمِّ ثِيَابَهُ","لَيْسَ الْكَرِيمُ عَلَى الْقَنَا بِمُحَرَّمِ"],["فَتَرَكْتُهُ جَزَرَ السِّبَاعِ يَنُشْنَهُ","يَقضِمْنَ حُسنَ بَنَانِهِ وَالْمِعْصَمِ"],["وَمِشَكِّ سَابِغَةٍ هَتَكْتُ فُرُوجَهَا","بِالسَّيْفِ عَنْ حَامِي الْحَقِيقَةِ مُعْلِمِ"],["رَبِذٍ يَدَاهُ بِالْقِدَاحِ إِذَا شَتَا","هَتَّاكِ غَايَاتِ التِّجَارِ مُلَوَّمِ"],["لَمَّا رَآنِي قَدْ نَزَلْتُ أُرِيدُهُ","أَبْدَي نَوَاجِذَهُ لِغَيْرِ تَبَسُّمِ"],["عَهْدِي بِهِ مَدَّ النَّهَارِ كَأَنَّمَا","خُضِبَ الْبَنَانُ وَرَأْسُهُ بِالْعِظْلَمِ"],["فَطَعَنْتُهُ بِالرُّمْحِ ثُمَّ عَلَوْتُهُ","بِمُهَنَّدٍ صَافِي الْحَدِيدَةِ مِخْذَمِ"],["بَطَلٍ كَأَنَّ ثِيَابَهُ فِي سَرْحَةٍ","يُحْذَى نِعَالَ السِّبْتِ لَيْسَ بِتَوْأَمِ"],["يَا شَاةَ مَا قَنَصٍ لِمَنْ حَلَّتْ لَهُ","حَرُمَتْ عَلَيَّ وَلَيْتَهَا لَمْ تَحْرُمِ"],["فَبَعَثْتُ جَارِيَتِي فَقُلْتُ لَهَا اذْهَبِي","فَتَجَسَّسِي أَخْبَارَهَا لِي وَاعْلَمِي"],["قَالَتْ رَأَيْتُ مِنَ الْأَعَادِي غِرَّةً","وَالشَّاةُ مُمْكِنَةٌ لِمَنْ هُوَ مُرْتَمِ"],["وَكَأَنَّمَا الْتَفَتَتْ بِجِيدِ جَدَايَةٍ","رَشَأٍ مِنَ الْغِزْلَانِ حُرٍّ أَرْثَمِ"],["نُبِّئْتُ عَمْرًا غَيْرَ شَاكِرِ نِعْمَتِي","وَالْكُفْرُ مَخْبَثَةٌ لِنَفْسِ الْمُنْعِمِ"],["وَلَقَدْ حَفِظْتُ وَصَاةَ عَمِّي بِالضُّحَى","إِذْ تَقْلِصُ الشَّفَتَانِ عَنْ وَضَحِ الْفَمِ"],["فِي حَوْمَةِ الْحَرِبِ الّتِي لَا تَشْتَكِي","غَمَرَاتِهَا الْأَبْطَالُ غَيْرَ تَغَمْغُمِ"],["إِذْ يَتَّقُونَ بِيَ الْأَسِنَّةَ لَمْ أَخِمْ","عَنْهَا وَلَكِنِّي تَضَايَقَ مُقْدَمِي"],["لَمَّا رَأَيْتُ الْقَوْمَ أَقْبَلَ جَمْعُهُمْ","يَتَذَامَرُونَ كَرَرْتُ غَيْرَ مُذَمَّمِ"],["يَدْعُونَ عَنْتَرَ وَالرِّمَاحُ كَأَنَّهَا","أَشْطَانُ بِئْرٍ فِي لَبَانِ الْأَدْهَمِ"],["مَا زِلْتُ أَرْمِيهِمْ بِثُغْرَةِ نَحْرِهِ","وَلَبَانِهِ حَتَّى تَسَرْبَلَ بِالدَّمِ"],["فَازْوَرَّ مِنْ وَقْعِ الْقَنَا بِلَبَانِهِ","وَشَكَا إِلَيَّ بِعَبْرَةٍ وَتَحَمْحُمِ"],["لَوْ كَانَ يَدْرِي مَا الْمُحَاوَرَةُ اشْتَكَى","وَلَكَانَ لَوْ عَلِمَ الْكَلَامَ مُكَلِّمِي"],["وَلَقَدْ شَفَى نَفْسِي وَأذْهَبَ سُقْمَهَا","قِيلُ الْفَوَارِسِ وَيْكَ عَنْتَرَ أَقْدِمِ"],["وَالْخَيْلُ تَقْتَحِمُ الْخَبَارَ عَوَابِسًا","مِنْ بَيْنِ شَيْظَمَةٍ وَأَجْرَدَ شَيْظَمِ"],["ذُلُلٌ رِكَابِي حَيْثُ شِئْتُ مُشَايِعِي","لُبِّي وَأَحْفِزُهُ بِأَمْرٍ مُبْرَمِ"],["وَلَقَدْ خَشِيتُ بِأَنْ أَمُوتَ وَلَمْ تَدُرْ","لِلْحَرْبِ دَائِرَةٌ عَلَى ابْنَيْ ضَمْضَمِ"],["الشَّاتِمَيْ عِرْضِي وَلَمْ أَشْتِمْهُمَا","وَالنَّاذِرَيْنِ إِذَا لَمَ الْقَهُمَا دَمِي"],["إِنْ يَفْعَلَا فَلَقَدْ تَرَكْتُ أَبَاهُمَا","جَزَرَ السِّبَاعِ وَكُلِّ نَسْرٍ قَشْعَمِ"]],"secs":{"1":"معلقة عنترة بن شداد"}}],"sharh":false};
